package dev.flovex.crates;

import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.command.*;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.block.Action;
import org.bukkit.event.inventory.*;
import org.bukkit.event.player.*;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;
import java.util.*;

public final class CratesMC extends JavaPlugin implements Listener, CommandExecutor {
  private NamespacedKey crateKey;
  private final Map<UUID,String> bindMode = new HashMap<>();
  private final Map<UUID,String> openCrate = new HashMap<>();
  private final Map<UUID,Inventory> openMenus = new HashMap<>();
  @Override public void onEnable(){ saveDefaultConfig(); crateKey=new NamespacedKey(this,"crate-key"); getServer().getPluginManager().registerEvents(this,this); Objects.requireNonNull(getCommand("sc")).setExecutor(this); getLogger().info("CratesMC enabled (license-free)."); }
  @Override public void onDisable(){bindMode.clear();openCrate.clear();openMenus.clear();}
  private String msg(String s){return ChatColor.translateAlternateColorCodes('&',getConfig().getString("messages.prefix", "&8[&6Crates&8] &r") + s);}
  private void send(Player p,String path){p.sendMessage(msg(getConfig().getString("messages."+path,"")));}
  private boolean admin(CommandSender s){if(s.hasPermission("cratesmc.admin"))return true;s.sendMessage(msg(getConfig().getString("messages.no-permission","&cYou do not have permission.")));return false;}
  private Set<String> crates(){ConfigurationSection c=getConfig().getConfigurationSection("crates");return c==null?Set.of():c.getKeys(false);}
  private ConfigurationSection crate(String id){return getConfig().getConfigurationSection("crates."+id.toLowerCase(Locale.ROOT));}
  private String nice(String s){return ChatColor.translateAlternateColorCodes('&',s.replace('_',' '));}
  private ItemStack keyItem(String crate,int amount){ConfigurationSection c=crate(crate);String material=getConfig().getString("keys."+crate+".material",getConfig().getString("settings.key-material","WHITE_CANDLE"));Material m;try{m=Material.valueOf(material.toUpperCase(Locale.ROOT));}catch(Exception e){m=Material.WHITE_CANDLE;}ItemStack item=new ItemStack(m,Math.max(1,Math.min(amount, m.getMaxStackSize())));ItemMeta meta=item.getItemMeta();meta.setDisplayName(nice(getConfig().getString("keys."+crate+".name",getConfig().getString("settings.key-default-name","&f&l%crate% Key").replace("%crate%",crate))));List<String> lore=getConfig().getStringList("keys."+crate+".lore");if(lore.isEmpty())lore=getConfig().getStringList("settings.key-default-lore");meta.setLore(lore.stream().map(x->nice(x.replace("%crate%",crate))).toList());meta.getPersistentDataContainer().set(crateKey,PersistentDataType.STRING,crate);item.setItemMeta(meta);return item;}
  private String getKey(ItemStack item){if(item==null||!item.hasItemMeta())return null;return item.getItemMeta().getPersistentDataContainer().get(crateKey,PersistentDataType.STRING);}
  private ItemStack rewardIcon(ConfigurationSection r){String mat=r.getString("material","DIAMOND");Material m;try{m=Material.valueOf(mat.toUpperCase(Locale.ROOT));}catch(Exception e){m=Material.CHEST;}ItemStack it=new ItemStack(m,Math.max(1,Math.min(64,r.getInt("amount",1))));ItemMeta im=it.getItemMeta();if(r.contains("name"))im.setDisplayName(nice(r.getString("name")));List<String> lore=r.getStringList("lore");if(!lore.isEmpty())im.setLore(lore.stream().map(this::nice).toList());for(String ench:r.getStringList("enchants")){String[] pair=ench.split(":");if(pair.length==2)try{im.addEnchant(org.bukkit.enchantments.Enchantment.getByName(pair[0].toUpperCase()),Integer.parseInt(pair[1]),true);}catch(Exception ignored){}}it.setItemMeta(im);return it;}
  private void giveKey(Player p,String id,int count){if(crate(id)==null){p.sendMessage(msg(getConfig().getString("messages.crate-missing","&cThat crate does not exist.")));return;}int left=count;while(left>0){int stack=Math.min(left,64);Map<Integer,ItemStack> overflow=p.getInventory().addItem(keyItem(id,stack));overflow.values().forEach(x->p.getWorld().dropItemNaturally(p.getLocation(),x));left-=stack;}p.sendMessage(msg(getConfig().getString("messages.key-received","&aYou received %amount% %crate% key(s).").replace("%amount%",String.valueOf(count)).replace("%crate%",id)));}
  private void openCrate(Player p,String id){ConfigurationSection c=crate(id);if(c==null)return;ConfigurationSection rewards=c.getConfigurationSection("rewards");if(rewards==null||rewards.getKeys(false).isEmpty()){p.sendMessage(msg("&cThis crate has no configured rewards."));return;}Inventory inv=Bukkit.createInventory(null,27,nice(c.getString("title","&8Choose a reward")));for(String n:rewards.getKeys(false)){ConfigurationSection r=rewards.getConfigurationSection(n);int slot=r.getInt("slot",Integer.parseInt(n)-1);if(slot>=0&&slot<inv.getSize())inv.setItem(slot,rewardIcon(r));}p.openInventory(inv);openCrate.put(p.getUniqueId(),id);openMenus.put(p.getUniqueId(),inv);}
  @Override public boolean onCommand(CommandSender s,Command cmd,String label,String[] a){if(a.length==0){s.sendMessage(msg("&f/sc bind <crate> &7- Bind crate to block"));s.sendMessage(msg("&f/sc givekey <player> <crate> <amount>"));s.sendMessage(msg("&f/sc keyall <crate> <amount>"));s.sendMessage(msg("&f/sc realkeygive <player> <crate> <amount>"));s.sendMessage(msg("&f/sc realkeyall <crate> <amount>"));s.sendMessage(msg("&f/sc view <crate> &7- Preview rewards"));s.sendMessage(msg("&f/sc keylist <player> &7- List keys"));s.sendMessage(msg("&f/sc keytake <player> <crate> <amount>"));s.sendMessage(msg("&f/sc keyclear <player> &7- Clear all crate keys"));s.sendMessage(msg("&f/sc reload"));return true;}
  String sub=a[0].toLowerCase(Locale.ROOT);if(sub.equals("view")&&a.length>=2){if(crate(a[1])==null){s.sendMessage(msg(getConfig().getString("messages.crate-missing","&cThat crate does not exist.")));return true;}if(s instanceof Player p)openCrate(p,a[1]);else s.sendMessage(msg("&cPlayer-only."));return true;}if(!admin(s))return true;
  try{switch(sub){case "bind": if(!(s instanceof Player p)||a.length<2){s.sendMessage(msg("&cUsage: /sc bind <crate>"));break;}if(crate(a[1])==null){s.sendMessage(msg("&cUnknown crate."));break;}bindMode.put(p.getUniqueId(),a[1].toLowerCase());p.sendMessage(msg("&aRight-click a block to bind &f"+a[1]+"&a. Sneak-right-click to cancel."));break;
  case "givekey": case "realkeygive": if(a.length<4){s.sendMessage(msg("&cUsage: /sc "+sub+" <player> <crate> <amount>"));break;}Player target=Bukkit.getPlayerExact(a[1]);if(target==null){s.sendMessage(msg("&cPlayer not online."));break;}giveKey(target,a[2],Integer.parseInt(a[3]));break;
  case "keyall": case "realkeyall": if(a.length<3){s.sendMessage(msg("&cUsage: /sc "+sub+" <crate> <amount>"));break;}int amount=Integer.parseInt(a[2]);for(Player online:Bukkit.getOnlinePlayers())giveKey(online,a[1],amount);break;
  case "keytake": if(a.length<4){s.sendMessage(msg("&cUsage: /sc keytake <player> <crate> <amount>"));break;}Player t=Bukkit.getPlayerExact(a[1]);if(t==null){s.sendMessage(msg("&cPlayer not online."));break;}int remove=Integer.parseInt(a[3]);for(int i=0;i<t.getInventory().getSize()&&remove>0;i++){ItemStack st=t.getInventory().getItem(i);if(a[2].equalsIgnoreCase(getKey(st))&&st!=null){int n=Math.min(remove,st.getAmount());st.setAmount(st.getAmount()-n);remove-=n;}}s.sendMessage(msg("&aKeys removed."));break;
  case "keyclear": if(a.length<2){s.sendMessage(msg("&cUsage: /sc keyclear <player>"));break;}Player tc=Bukkit.getPlayerExact(a[1]);if(tc==null){s.sendMessage(msg("&cPlayer not online."));break;}for(int i=0;i<tc.getInventory().getSize();i++){if(getKey(tc.getInventory().getItem(i))!=null)tc.getInventory().setItem(i,null);}s.sendMessage(msg("&aCleared crate keys."));break;
  case "keylist": if(a.length<2){s.sendMessage(msg("&cUsage: /sc keylist <player>"));break;}Player kl=Bukkit.getPlayerExact(a[1]);if(kl==null){s.sendMessage(msg("&cPlayer not online."));break;}s.sendMessage(msg("&f"+kl.getName()+"'s keys:"));for(String id:crates()){int count=0;for(ItemStack st:kl.getInventory().getContents())if(id.equalsIgnoreCase(getKey(st))&&st!=null)count+=st.getAmount();s.sendMessage(msg("&7"+id+": &f"+count));}break;
  case "reload": reloadConfig();s.sendMessage(msg("&aConfig reloaded."));break;
  default:s.sendMessage(msg("&cUnknown subcommand. Use /sc."));}}
  catch(Exception ex){s.sendMessage(msg("&cInvalid command arguments."));getLogger().warning("Command failure: "+ex.getMessage());}return true;}
  @EventHandler public void onInteract(PlayerInteractEvent e){if(e.getAction()!=Action.RIGHT_CLICK_BLOCK)return;Player p=e.getPlayer();String bind=bindMode.get(p.getUniqueId());if(bind!=null){if(p.isSneaking()){bindMode.remove(p.getUniqueId());p.sendMessage(msg("&cBinding cancelled."));return;}Block b=e.getClickedBlock();if(b!=null){getConfig().set("settings.bound-blocks."+b.getWorld().getName()+"."+b.getX()+"_"+b.getY()+"_"+b.getZ(),bind);saveConfig();bindMode.remove(p.getUniqueId());p.sendMessage(msg("&aBound block to &f"+bind));e.setCancelled(true);}return;}ItemStack hand=e.getItem();String key=getKey(hand);if(key!=null&&crate(key)!=null){e.setCancelled(true);if(hand.getAmount()>1)hand.setAmount(hand.getAmount()-1);else p.getInventory().setItem(e.getHand()==org.bukkit.inventory.EquipmentSlot.HAND? p.getInventory().getHeldItemSlot():p.getInventory().getHeldItemSlot(),null);openCrate(p,key);return;}Block b=e.getClickedBlock();if(b!=null){String path="settings.bound-blocks."+b.getWorld().getName()+"."+b.getX()+"_"+b.getY()+"_"+b.getZ();String id=getConfig().getString(path);if(id!=null){e.setCancelled(true);openCrate(p,id);}}}
  @EventHandler public void onClick(InventoryClickEvent e){UUID id=e.getWhoClicked().getUniqueId();Inventory menu=openMenus.get(id);if(menu==null||e.getView().getTopInventory()!=menu)return;e.setCancelled(true);if(e.getRawSlot()<0||e.getRawSlot()>=menu.getSize())return;Player p=(Player)e.getWhoClicked();String crateId=openCrate.get(id);ConfigurationSection reward=crate(crateId).getConfigurationSection("rewards."+(e.getRawSlot()+1));if(reward==null){for(String key:crate(crateId).getConfigurationSection("rewards").getKeys(false)){ConfigurationSection r=crate(crateId).getConfigurationSection("rewards."+key);if(r.getInt("slot",Integer.parseInt(key)-1)==e.getRawSlot()){reward=r;break;}}}if(reward==null)return;ItemStack key=p.getInventory().getItemInMainHand();// Reward selection is implemented by configured reward index/slot.
    List<String> commands=reward.getStringList("commands");ItemStack rewardItem=rewardIcon(reward);if(commands.isEmpty())p.getInventory().addItem(rewardItem).values().forEach(x->p.getWorld().dropItemNaturally(p.getLocation(),x));else for(String command:commands)Bukkit.dispatchCommand(Bukkit.getConsoleSender(),command.replace("%player%",p.getName()));p.closeInventory();openMenus.remove(id);openCrate.remove(id);p.sendMessage(msg(getConfig().getString("messages.crate-opened","&aCrate opened!")));String sound=getConfig().getString("settings.sounds.win","ENTITY_PLAYER_LEVELUP");try{p.playSound(p.getLocation(),Sound.valueOf(sound),1f,1f);}catch(Exception ignored){} }
  @EventHandler public void onClose(InventoryCloseEvent e){UUID id=e.getPlayer().getUniqueId();if(openMenus.get(id)==e.getView().getTopInventory()){openMenus.remove(id);openCrate.remove(id);}}
}
